    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;

    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    let residual_score = node_residual_cpu as f64 + node_residual_ram as f64;

    let dynamic_horizon_factor = step_index as f64 / total_jobs as f64;

    let lookahead_score = if next_job_cpu <= node_residual_cpu && next_job_ram <= node_residual_ram {
        0.9 // Prefer nodes that can fit the next job without wasting capacity
    } else {
        1.0
    };

    let score = residual_score + imbalance_penalty * dynamic_horizon_factor * lookahead_score;

    score
}

