pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Dynamic horizon awareness
    let step_normalized = step_index as f64 / total_jobs as f64;
    let penalty_step = if step_normalized < 0.3 { 1.0 } else if step_normalized > 0.7 { 2.0 } else { 1.5 };

    // Lookahead awareness
    let next_job_fits_cpu = node_residual_cpu >= next_job_cpu;
    let next_job_fits_ram = node_residual_ram >= next_job_ram;
    let lookahead_penalty = if next_job_fits_cpu && next_job_fits_ram { 0.0 } else { 1.5 };

    // Non-linear conditionals
    let cpu_overload_penalty = (node_residual_cpu as f64 / mean_cpu_residual).powi(2);
    let ram_overload_penalty = (node_residual_ram as f64 / mean_ram_residual).powi(2);

    // Imbalance penalties
    let cpu_imbalance_bonus = if cpu_norm < 0.5 { -1.0 } else { 1.0 };
    let ram_imbalance_bonus = if ram_norm < 0.5 { -1.0 } else { 1.0 };

    // Fine-grained residual fitting
    let cpu_fitting_ratio = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_fitting_ratio = node_residual_ram as f64 / node_capacity_ram as f64;
    let fine_grained_penalty = (cpu_fitting_ratio - 1.0).powi(2) + (ram_fitting_ratio - 1.0).powi(2);

    // Lookahead packing bonus
    let lookahead_bonus = if next_job_fits_cpu && next_job_fits_ram { 0.5 } else { 0.0 };

    // Combine all components
    let score = cpu_norm + ram_norm - imbalance_penalty + penalty_step + lookahead_penalty - cpu_overload_penalty - ram_overload_penalty + cpu_imbalance_bonus + ram_imbalance_bonus - fine_grained_penalty + lookahead_bonus;
    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    let node_utilization = 1.0 - (node_residual_cpu as f64 / node_capacity_cpu as f64 + node_residual_ram as f64 / node_capacity_ram as f64) / 2.0;
    let horizon_factor = ((step_index as f64 + 1.0) / total_jobs as f64).powi(3);

    let lookahead_factor = if next_job_cpu == job_cpu && next_job_ram == job_ram { 0.5 } else { 1.0 };

    // Non-linear conditionals and lookahead packing bonuses
    let lookahead_bonus = if step_index < total_jobs / 4 { 0.2 } else if step_index < total_jobs / 2 { 0.1 } else { 0.05 };
    let pack_factor = if node_residual_cpu <= next_job_cpu && node_residual_ram <= next_job_ram { 0.3 } else { 0.1 };

    // Imbalance penalties
    let cpu_imbalance_penalty = (node_capacity_cpu as f64 - job_cpu as f64) / node_capacity_cpu as f64;
    let ram_imbalance_penalty = (node_capacity_ram as f64 - job_ram as f64) / node_capacity_ram as f64;

    // Horizon-aware placement logic
    let horizon_weight = if step_index < total_jobs / 8 { 0.5 } else { 1.0 };

    // Fine-grained residual fitting with lookahead anticipation
    let fine_grained_cpu_fit = (node_residual_cpu as f64 - mean_cpu_residual).powi(2);
    let fine_grained_ram_fit = (node_residual_ram as f64 - mean_ram_residual).powi(2);
    let lookahead_rescue_bonus = if node_residual_cpu <= next_job_cpu / 2 && node_residual_ram <= next_job_ram / 2 { 0.1 } else { 0.0 };

    // Lookahead packing bonuses and penalties
    let lookahead_packing_bonus = if node_residual_cpu <= next_job_cpu + job_cpu && node_residual_ram <= next_job_ram + job_ram { 0.2 } else { 0.0 };
    let lookahead_penalize_overfitting = if (node_residual_cpu as f64 - mean_cpu_residual).abs() > fine_grained_cpu_fit || (node_residual_ram as f64 - mean_ram_residual).abs() > fine_grained_ram_fit { 0.1 } else { 0.0 };

    // Final score calculation
    let score = cpu_norm + ram_norm 
        - imbalance_penalty 
        - cpu_imbalance_penalty 
        - ram_imbalance_penalty 
        + node_utilization * horizon_factor * lookahead_factor * lookahead_bonus * pack_factor * horizon_weight * fine_grained_cpu_fit * fine_grained_ram_fit * lookahead_rescue_bonus
        + lookahead_packing_bonus 
        - lookahead_penalize_overfitting;
    score
}
